/*
* Motor del juego que contiene la lógica principal
* Implementar:
* - Gestión del estado del juego
* - Validación de movimientos
* - Cálculo de combates
* - Cálculo de recursos
*/

import { GameState, Hero, Position, MapTile, Resources, Unit } from '../types/game';

// Calcula si un héroe puede moverse a una posición
export const canMoveToPosition = (hero: Hero, target: Position, map: MapTile[][]): boolean => {
  // Implementar validación de movimiento basada en:
  // - Distancia (según puntos de movimiento)
  // - Tipo de terreno (algunos terrenos cuestan más)
  // - Obstáculos (montañas, agua, etc.)
  
  // Implementar algoritmo de pathfinding (A*) para encontrar el camino más corto
  
  return false; // Placeholder
};

// Calcula el coste de movimiento entre celdas
export const calculateMovementCost = (from: MapTile, to: MapTile): number => {
  // Implementar cálculo basado en tipo de terreno
  switch (to.terrain) {
    case 'grass': return 1;
    case 'forest': return 2;
    case 'mountain': return 3;
    case 'water': return Infinity; // No se puede atravesar sin barco
    case 'desert': return 2;
    case 'snow': return 2;
    default: return 1;
  }
};

// Simula un combate entre dos ejércitos
export const simulateCombat = (attackerArmy: Unit[], defenderArmy: Unit[]): {
  winner: 'attacker' | 'defender',
  attackerLosses: Unit[],
  defenderLosses: Unit[],
} => {
  // Implementar algoritmo de combate que considere:
  // - Estadísticas de las unidades
  // - Cantidad de unidades
  // - Modificadores de terreno
  
  return {
    winner: 'attacker', // Placeholder
    attackerLosses: [],
    defenderLosses: [],
  };
};

// Calcula los recursos generados al final del turno
export const calculateEndTurnResources = (gameState: GameState, current: 'player' | 'ai'): Resources => {
  const entity = gameState[current];
  
  // Recursos base
  const resources: Resources = {
    gold: 0,
    wood: 0,
    stone: 0
  };
  
  // Recursos de ciudades y edificios
  entity.cities.forEach(city => {
    city.buildings.forEach(building => {
      if (building.is_castle) {
        // Recursos base del castillo
        resources.gold += 500;
      }
    });
  });
  
  // Recursos de minas
  gameState.map.visible_objects?.forEach(obj => {
    if ('resource_type' in obj && obj.owner === current) {
      const resource = obj.resource_type as keyof Resources;
      resources[resource] = (resources[resource] || 0) + obj.resource_per_turn;
    }
  });
  
  return resources;
};

// Prepara el estado del juego para el siguiente turno
export const prepareNextTurn = (gameState: GameState): GameState => {
  const newState = { ...gameState };
  
  // Cambiar el jugador actual
  newState.current_player = newState.current_player === 'player' ? 'ai' : 'player';
  
  // Incrementar turno si vuelve al jugador
  if (newState.current_player === 'player') {
    newState.turn += 1;
  }
  
  // Restaurar puntos de movimiento de los héroes del jugador actual
  const currentEntity = newState[newState.current_player];
  currentEntity.heroes.forEach(hero => {
    hero.stats.movement_points_left = hero.stats.movement_points;
  });
  
  // Actualizar recursos
  const newResources = calculateEndTurnResources(gameState, newState.current_player);
  const entity = newState[newState.current_player];
  
  entity.resources = {
    gold: entity.resources.gold + newResources.gold,
    wood: entity.resources.wood + newResources.wood,
    stone: entity.resources.stone + newResources.stone
  };
  
  // Actualizar unidades disponibles semanalmente
  if (newState.turn % 7 === 1) {
    currentEntity.cities.forEach(city => {
      city.buildings.forEach(building => {
        if (building.can_recruit) {
          building.available_creatures.forEach(creature => {
            creature.count += creature.growth_per_week;
          });
        }
      });
    });
  }
  
  return newState;
};
